def Optional_Settings(action, scope, user_id=None, body=None, **_extra):
    import json, os, datetime, time, re, uuid, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0263000" if __import__("os").path.isdir("./environment_mix/0263000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _safe_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:12].upper()}"

    def _audit(endpoint, credential_id, status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("req"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _touch_settings_uniqueness(rows):
        # Enforce uniqueness invariants by keeping only the most recently updated row per scope/user.
        # This is a defensive normalization; updates will still validate and not create duplicates.
        global_rows = [r for r in rows if r.get("scope") == "global"]
        if len(global_rows) > 1:
            def key(r):
                dt = _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or datetime.datetime.min
                return dt
            keep = max(global_rows, key=key)
            rows = [r for r in rows if not (r.get("scope") == "global" and r.get("id") != keep.get("id"))]
        # per user
        by_user = {}
        for r in rows:
            if r.get("scope") == "user" and r.get("user_id"):
                by_user.setdefault(r["user_id"], []).append(r)
        for uid, rr in by_user.items():
            if len(rr) > 1:
                def key(r):
                    dt = _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or datetime.datetime.min
                    return dt
                keep = max(rr, key=key)
                rows = [r for r in rows if not (r.get("scope") == "user" and r.get("user_id") == uid and r.get("id") != keep.get("id"))]
        return rows

    endpoint = "Optional Settings"
    credential_id = None  # ambient auth, no explicit credential param

    # Validation (schema)
    if action not in ("get", "update"):
        _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid action.", field="action")
    if scope not in ("global", "user"):
        _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid scope.", field="scope")
    if scope == "user":
        if user_id is None or not isinstance(user_id, str) or not re.match(r"^usr_[0-9A-Z]{4,}$", user_id):
            _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "user_id is required and must be a valid user id when scope='user'.", field="user_id")
    else:
        if user_id is not None:
            # allow but must be null in underlying row; treat as validation error for tool contract
            _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "user_id must not be provided when scope='global'.", field="user_id")

    if action == "update":
        if body is None or not isinstance(body, dict):
            _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "body must be an object for action=update.", field="body")
        allowed = {"auth_mode", "default_server_id", "redact_secrets_in_logs", "request_timeout_ms", "max_concurrent_requests", "status"}
        for k in body.keys():
            if k not in allowed:
                _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Unknown field in body.", field=k)
        if "auth_mode" in body and body["auth_mode"] not in ("none", "pat", "oauth"):
            _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid auth_mode.", field="auth_mode")
        if "status" in body and body["status"] not in ("active", "disabled"):
            _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")
        if "redact_secrets_in_logs" in body and not isinstance(body["redact_secrets_in_logs"], bool):
            _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "redact_secrets_in_logs must be boolean.", field="redact_secrets_in_logs")
        if "request_timeout_ms" in body:
            if not _safe_int(body["request_timeout_ms"]):
                _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "request_timeout_ms must be integer.", field="request_timeout_ms")
            # Tool description says >=0, but collection constraint is 1000..120000. Enforce schema constraint.
            if body["request_timeout_ms"] < 1000 or body["request_timeout_ms"] > 120000:
                _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "request_timeout_ms must be between 1000 and 120000.", field="request_timeout_ms")
        if "max_concurrent_requests" in body:
            if not _safe_int(body["max_concurrent_requests"]):
                _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "max_concurrent_requests must be integer.", field="max_concurrent_requests")
            if body["max_concurrent_requests"] < 1 or body["max_concurrent_requests"] > 200:
                _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "max_concurrent_requests must be between 1 and 200.", field="max_concurrent_requests")
        if "default_server_id" in body:
            if body["default_server_id"] is not None:
                if not isinstance(body["default_server_id"], str) or not re.match(r"^sb_srv_[0-9A-Z]{4,}$", body["default_server_id"]):
                    _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "default_server_id must be a valid server id.", field="default_server_id")

    # Load store
    settings = _load("mcp_settings.json")
    users = _load("users.json")
    servers = _load("supabase_servers.json")

    if not isinstance(settings, list): settings = []
    if not isinstance(users, list): users = []
    if not isinstance(servers, list): servers = []

    settings = _touch_settings_uniqueness(settings)

    # helper to find record
    def _find_settings(scope, user_id):
        for r in settings:
            if r.get("scope") == scope and (r.get("user_id") == user_id):
                return r
        return None

    # Resolve/validate references for scope=user
    if scope == "user":
        u = next((x for x in users if x.get("id") == user_id), None)
        if u is None:
            _audit(endpoint, credential_id, "error", "NOT_FOUND")
            return _err("NOT_FOUND", "User not found.", id=user_id)
        # allow suspended/deleted to still have settings read; business rules don't forbid settings access

    # action=get
    if action == "get":
        if scope == "global":
            rec = _find_settings("global", None)
            if rec is None:
                # return empty result (read with no match -> empty set)
                _audit(endpoint, credential_id, "ok", None)
                return {"data": None}
            _audit(endpoint, credential_id, "ok", None)
            return {"data": rec}
        else:
            rec = _find_settings("user", user_id)
            if rec is None:
                _audit(endpoint, credential_id, "ok", None)
                return {"data": None}
            _audit(endpoint, credential_id, "ok", None)
            return {"data": rec}

    # action=update
    # Business rule: update should upsert exactly one active settings row per scope,
    # but tool description: return NOT_FOUND if scope=user and referenced user settings record d...
    # Interpret as: for scope=user, must already exist; for global, upsert allowed.
    target_user = None if scope == "global" else user_id
    rec = _find_settings(scope, target_user)

    if scope == "user" and rec is None:
        _audit(endpoint, credential_id, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "User-scoped settings record not found.", scope=scope, user_id=user_id)

    if rec is None:
        # create only for global
        rec = {
            "id": _gen_id("mcp_set"),
            "scope": "global",
            "user_id": None,
            "auth_mode": "none",
            "default_server_id": None,
            "redact_secrets_in_logs": True,
            "request_timeout_ms": 30000,
            "max_concurrent_requests": 10,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        settings.append(rec)

    # Validate default_server_id ownership policy
    if "default_server_id" in body:
        ds = body["default_server_id"]
        if ds is None:
            pass
        else:
            srv = next((s for s in servers if s.get("id") == ds), None)
            if srv is None:
                _audit(endpoint, credential_id, "error", "NOT_FOUND")
                return _err("NOT_FOUND", "default_server_id references a server that does not exist.", default_server_id=ds)
            if scope == "user":
                if srv.get("owner_user_id") != user_id:
                    _audit(endpoint, credential_id, "error", "UNAUTHORIZED")
                    return _err("UNAUTHORIZED", "default_server_id must reference a server owned by the same user.", default_server_id=ds)
            else:
                # global: "visible to the system" enforced by policy; offline store -> accept any non-revoked server
                if srv.get("status") == "revoked":
                    _audit(endpoint, credential_id, "error", "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Global default_server_id cannot reference a revoked server.", default_server_id=ds)

    # Lifecycle transition check (status)
    if "status" in body:
        old = rec.get("status")
        new = body["status"]
        if old != new:
            allowed = {"active": ["disabled"], "disabled": ["active"]}
            if old not in allowed or new not in allowed.get(old, []):
                _audit(endpoint, credential_id, "error", "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=old, to_status=new)

    # Apply updates
    for k, v in body.items():
        rec[k] = v
    rec["updated_at"] = now

    # Ensure uniqueness invariants after update
    settings = _touch_settings_uniqueness(settings)

    _save("mcp_settings.json", settings)
    _audit(endpoint, credential_id, "ok", None)
    return {"data": rec}

def Who_Am_I(credential, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0263000" if __import__("os").path.isdir("./environment_mix/0263000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return _load("request_logs.json")

    def _log_call(endpoint, credential_id, status, latency_ms, user_id=None, error_code=None):
        logs = _ensure_request_logs()
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "user_id": user_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _resolve_credential(cred_value):
        # Authenticate by matching caller-supplied value against:
        # - credentials.id
        # - credentials.secret_fingerprint (client-visible API key / token id surrogate)
        # - auth_sessions.id (treat as bearer token)
        # Never compare against secret_ciphertext.
        credentials = _load("credentials.json")
        sessions = _load("auth_sessions.json")
        users = _load("users.json")

        now_dt = datetime.datetime.utcnow()

        # Pre-expire sessions if needed (business rule)
        changed = False
        for s in sessions:
            if s.get("status") == "active":
                revoked_at = _parse_dt(s.get("revoked_at"))
                if revoked_at is not None:
                    s["status"] = "revoked"
                    s["updated_at"] = _now()
                    changed = True
                    continue
                exp = _parse_dt(s.get("expires_at"))
                if exp is not None and exp <= now_dt:
                    s["status"] = "expired"
                    s["updated_at"] = _now()
                    changed = True
        if changed:
            _save("auth_sessions.json", sessions)

        # 1) Session token path
        for s in sessions:
            if cred_value == s.get("id"):
                if s.get("status") != "active":
                    return None, None, None
                uid = s.get("user_id")
                user = next((u for u in users if u.get("id") == uid), None)
                if not user or user.get("status") != "active":
                    return None, None, None
                cred_id = s.get("credential_id")
                cred = None
                if cred_id:
                    cred = next((c for c in credentials if c.get("id") == cred_id), None)
                    if not cred or cred.get("status") != "active":
                        return None, None, None
                    exp = _parse_dt(cred.get("expires_at"))
                    if exp is not None and exp <= now_dt:
                        return None, None, None
                return user, s, cred

        # 2) Direct credential path (id or fingerprint)
        for c in credentials:
            if cred_value == c.get("id") or cred_value == c.get("secret_fingerprint"):
                if c.get("status") != "active":
                    return None, None, None
                exp = _parse_dt(c.get("expires_at"))
                if exp is not None and exp <= now_dt:
                    return None, None, None
                uid = c.get("user_id")
                user = next((u for u in users if u.get("id") == uid), None)
                if not user or user.get("status") != "active":
                    return None, None, None
                return user, None, c

        return None, None, None

    start = time.time()

    # Validate input
    if not isinstance(credential, str) or not credential.strip():
        latency = (time.time() - start) * 1000
        _log_call("Who Am I", None, "error", latency, user_id=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "credential must be a non-empty string")

    user, session, cred = _resolve_credential(credential.strip())
    if not user:
        latency = (time.time() - start) * 1000
        _log_call("Who Am I", None, "error", latency, user_id=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid credentials")

    # Rate limit / quota enforcement (observable dynamics)
    # Policy: per credential/user - max 60 requests per rolling 60s; max 10,000 requests per rolling 24h
    logs = _ensure_request_logs()
    now_dt = datetime.datetime.utcnow()
    window_60s = now_dt - datetime.timedelta(seconds=60)
    window_24h = now_dt - datetime.timedelta(hours=24)

    uid = user.get("id")
    cred_id = (cred or {}).get("id") if cred else (session or {}).get("credential_id") or (session or {}).get("id")
    # If authenticated via session without credential_id, use session id as identifier
    identifier = cred_id or (session.get("id") if session else None) or uid

    def _log_dt(row):
        return _parse_dt(row.get("created_at"))

    recent_60 = 0
    recent_24h = 0
    for r in logs:
        if r.get("user_id") != uid:
            continue
        dt = _log_dt(r)
        if not dt:
            continue
        if dt >= window_60s:
            recent_60 += 1
        if dt >= window_24h:
            recent_24h += 1

    # Enforce before logging this call's success (so the violating call is refused and still logged as error)
    if recent_60 >= 60:
        latency = (time.time() - start) * 1000
        _log_call("Who Am I", identifier, "error", latency, user_id=uid, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded", limit=60, window_seconds=60, used=recent_60)

    if recent_24h >= 10000:
        latency = (time.time() - start) * 1000
        _log_call("Who Am I", identifier, "error", latency, user_id=uid, error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=10000, window_seconds=86400, used=recent_24h)

    # Update last_used_at on credential if present
    if cred:
        credentials = _load("credentials.json")
        for c in credentials:
            if c.get("id") == cred.get("id"):
                c["last_used_at"] = _now()
                c["updated_at"] = _now()
                break
        _save("credentials.json", credentials)

    # Prepare response
    mcp_settings = _load("mcp_settings.json")
    # Choose user settings if present, else global
    user_settings = next((s for s in mcp_settings if s.get("scope") == "user" and s.get("user_id") == uid and s.get("status") == "active"), None)
    global_settings = next((s for s in mcp_settings if s.get("scope") == "global" and s.get("user_id") in (None, "") and s.get("status") == "active"), None)

    auth_mode = None
    if user_settings:
        auth_mode = user_settings.get("auth_mode")
    elif global_settings:
        auth_mode = global_settings.get("auth_mode")

    granted_scopes = ["read:servers", "write:servers"]
    if auth_mode == "none":
        granted_scopes.append("auth:none")
    elif auth_mode == "pat":
        granted_scopes.append("auth:pat")
    elif auth_mode == "oauth":
        granted_scopes.append("auth:oauth")

    # Consumption computed including this call? typical APIs show after-this-call; we will log after building response.
    usage = {
        "rate_limit": {"limit": 60, "window_seconds": 60, "used": recent_60, "remaining": max(0, 60 - recent_60)},
        "quota": {"limit": 10000, "window_seconds": 86400, "used": recent_24h, "remaining": max(0, 10000 - recent_24h)},
    }

    latency = (time.time() - start) * 1000
    _log_call("Who Am I", identifier, "ok", latency, user_id=uid, error_code=None)

    return {
        "user": {
            "id": user.get("id"),
            "email": user.get("email"),
            "display_name": user.get("display_name"),
            "status": user.get("status"),
        },
        "credential": {
            "authenticated_via": "session" if session else "credential",
            "id": (cred or {}).get("id") if cred else (session.get("credential_id") if session else None),
            "type": (cred or {}).get("type") if cred else None,
        },
        "granted_scopes": granted_scopes,
        "usage": usage,
        "timestamp": _now(),
    }

def Users(action, credential, id=None, status=None, email=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, uuid, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0263000" if __import__("os").path.isdir("./environment_mix/0263000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:12].upper()}"

    def _audit(credential_id, status_s, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("req"),
            "endpoint": "Users",
            "credential_id": credential_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _safe_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    if action not in ("list", "get"):
        _audit(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid action.", field="action")
    if not isinstance(credential, str) or not credential.strip():
        _audit(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "credential must be a non-empty string.", field="credential")

    credentials = _load("credentials.json")
    users = _load("users.json")
    logs = _load("request_logs.json")
    if not isinstance(credentials, list): credentials = []
    if not isinstance(users, list): users = []
    if not isinstance(logs, list): logs = []

    cred = next((c for c in credentials if c.get("id") == credential or c.get("secret_fingerprint") == credential), None)
    if cred is None or cred.get("status") != "active":
        _audit(cred.get("id") if cred else None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid credential.")
    exp = _parse_dt(cred.get("expires_at"))
    if exp is not None and exp <= now_dt:
        _audit(cred.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Credential has expired.", credential_id=cred.get("id"))

    acting_user = next((u for u in users if u.get("id") == cred.get("user_id")), None)
    if acting_user is None or acting_user.get("status") != "active":
        _audit(cred.get("id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "User is not active for this credential.", user_id=cred.get("user_id"))

    # Rate limit / quota
    window_s = 60
    day_s = 86400
    w_start = now_dt - datetime.timedelta(seconds=window_s)
    d_start = now_dt - datetime.timedelta(seconds=day_s)
    def _log_time(r): return _parse_dt(r.get("created_at"))
    recent = [r for r in logs if r.get("credential_id") == cred.get("id") and (_log_time(r) is not None) and _log_time(r) >= w_start]
    daily = [r for r in logs if r.get("credential_id") == cred.get("id") and (_log_time(r) is not None) and _log_time(r) >= d_start]
    if len(recent) >= 120:
        _audit(cred.get("id"), "error", "RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded.")
    if len(daily) >= 10000:
        _audit(cred.get("id"), "error", "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")

    # Update last_used_at
    cred["last_used_at"] = now
    cred["updated_at"] = now
    for i, c in enumerate(credentials):
        if c.get("id") == cred.get("id"):
            credentials[i] = cred
            break
    _save("credentials.json", credentials)

    if action == "get":
        if id is None or not isinstance(id, str) or not re.match(r"^usr_[0-9A-Z]{4,}$", id):
            _audit(cred.get("id"), "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "id is required and must be a valid user id.", field="id")
        u = next((x for x in users if x.get("id") == id), None)
        if u is None:
            _audit(cred.get("id"), "error", "NOT_FOUND")
            return _err("NOT_FOUND", "User not found.", id=id)
        _audit(cred.get("id"), "ok", None)
        return {"data": u}

    # action=list
    if status is not None and status not in ("active", "suspended", "deleted"):
        _audit(cred.get("id"), "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if email is not None and not isinstance(email, str):
        _audit(cred.get("id"), "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "email must be a string.", field="email")
    if limit is None:
        limit = 50
    if not _safe_int(limit) or limit < 1 or limit > 200:
        _audit(cred.get("id"), "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _audit(cred.get("id"), "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            if not raw.startswith("i:"):
                raise ValueError("bad cursor")
            start = int(raw.split(":", 1)[1])
            if start < 0:
                raise ValueError("bad cursor")
        except Exception:
            _audit(cred.get("id"), "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    rows = users[:]
    if status is not None:
        rows = [u for u in rows if u.get("status") == status]
    if email is not None:
        rows = [u for u in rows if u.get("email") == email]

    # deterministic order: created_at desc then id
    def _sort_key(u):
        dt = _parse_dt(u.get("created_at")) or datetime.datetime.min
        return (-int(dt.timestamp()), str(u.get("id") or ""))
    rows.sort(key=_sort_key)

    total = len(rows)
    page = rows[start:start + limit]
    next_cursor = None
    has_more = start + limit < total
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"i:{start+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    _audit(cred.get("id"), "ok", None)
    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor}
    }

def Supabase_Servers(action, credential, id=None, owner_user_id=None, supabase_project_ref=None, status=None, limit=None, cursor=None, body=None, **_extra):
    import json, os, datetime, time, re, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0263000" if __import__("os").path.isdir("./environment_mix/0263000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_request_logs():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return _load("request_logs.json")

    def _log_call(endpoint, credential_id, status_s, latency_ms, user_id=None, error_code=None, meta=None):
        logs = _ensure_request_logs()
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "user_id": user_id,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int(latency_ms),
            "created_at": _now(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _resolve_credential(cred_value):
        credentials = _load("credentials.json")
        sessions = _load("auth_sessions.json")
        users = _load("users.json")
        now_dt = datetime.datetime.utcnow()

        # Expire sessions if needed (business rule)
        changed = False
        for s in sessions:
            if s.get("status") == "active":
                revoked_at = _parse_dt(s.get("revoked_at"))
                if revoked_at is not None:
                    s["status"] = "revoked"
                    s["updated_at"] = _now()
                    changed = True
                    continue
                exp = _parse_dt(s.get("expires_at"))
                if exp is not None and exp <= now_dt:
                    s["status"] = "expired"
                    s["updated_at"] = _now()
                    changed = True
        if changed:
            _save("auth_sessions.json", sessions)

        # Session token
        for s in sessions:
            if cred_value == s.get("id"):
                if s.get("status") != "active":
                    return None, None, None
                uid = s.get("user_id")
                user = next((u for u in users if u.get("id") == uid), None)
                if not user or user.get("status") != "active":
                    return None, None, None
                cred_id = s.get("credential_id")
                cred = None
                if cred_id:
                    cred = next((c for c in credentials if c.get("id") == cred_id), None)
                    if not cred or cred.get("status") != "active":
                        return None, None, None
                    exp = _parse_dt(cred.get("expires_at"))
                    if exp is not None and exp <= now_dt:
                        return None, None, None
                return user, s, cred

        # Direct credential
        for c in credentials:
            if cred_value == c.get("id") or cred_value == c.get("secret_fingerprint"):
                if c.get("status") != "active":
                    return None, None, None
                exp = _parse_dt(c.get("expires_at"))
                if exp is not None and exp <= now_dt:
                    return None, None, None
                uid = c.get("user_id")
                user = next((u for u in users if u.get("id") == uid), None)
                if not user or user.get("status") != "active":
                    return None, None, None
                return user, None, c

        return None, None, None

    def _enforce_limits(user_id, identifier, endpoint, start_time):
        logs = _ensure_request_logs()
        now_dt = datetime.datetime.utcnow()
        window_60s = now_dt - datetime.timedelta(seconds=60)
        window_24h = now_dt - datetime.timedelta(hours=24)

        def _log_dt(row):
            return _parse_dt(row.get("created_at"))

        recent_60 = 0
        recent_24h = 0
        for r in logs:
            if r.get("user_id") != user_id:
                continue
            dt = _log_dt(r)
            if not dt:
                continue
            if dt >= window_60s:
                recent_60 += 1
            if dt >= window_24h:
                recent_24h += 1

        if recent_60 >= 60:
            latency = (time.time() - start_time) * 1000
            _log_call(endpoint, identifier, "error", latency, user_id=user_id, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=60, window_seconds=60, used=recent_60)

        if recent_24h >= 10000:
            latency = (time.time() - start_time) * 1000
            _log_call(endpoint, identifier, "error", latency, user_id=user_id, error_code="QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit=10000, window_seconds=86400, used=recent_24h)

        return None

    def _valid_uri_https(u):
        if not isinstance(u, str) or not u:
            return False
        try:
            p = urllib.parse.urlparse(u)
            return p.scheme == "https" and bool(p.netloc)
        except Exception:
            return False

    def _gen_id(prefix):
        # ULID-ish: time component + random base32
        import secrets
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        t = int(datetime.datetime.utcnow().timestamp() * 1000)
        # 10 chars time (base32-ish)
        def _b32(n, l):
            s = ""
            for _ in range(l):
                s = alphabet[n % 32] + s
                n //= 32
            return s
        time_part = _b32(t, 10)
        rand_part = "".join(secrets.choice(alphabet) for _ in range(10))
        return f"{prefix}_{time_part}{rand_part}"

    start = time.time()
    endpoint = "Supabase Servers"

    # Validate basics
    if not isinstance(action, str) or action not in ("list", "get", "create", "update"):
        latency = (time.time() - start) * 1000
        _log_call(endpoint, None, "error", latency, user_id=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "action must be one of: list, get, create, update")

    if not isinstance(credential, str) or not credential.strip():
        latency = (time.time() - start) * 1000
        _log_call(endpoint, None, "error", latency, user_id=None, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "credential must be a non-empty string")

    user, session, cred = _resolve_credential(credential.strip())
    if not user:
        latency = (time.time() - start) * 1000
        _log_call(endpoint, None, "error", latency, user_id=None, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Missing or invalid credentials")

    uid = user.get("id")
    identifier = (cred or {}).get("id") if cred else (session.get("credential_id") if session else None) or (session.get("id") if session else None) or uid

    limit_err = _enforce_limits(uid, identifier, endpoint, start)
    if limit_err:
        return limit_err

    # Update credential last_used_at if present
    if cred:
        credentials = _load("credentials.json")
        for c in credentials:
            if c.get("id") == cred.get("id"):
                c["last_used_at"] = _now()
                c["updated_at"] = _now()
                break
        _save("credentials.json", credentials)

    servers = _load("supabase_servers.json")
    users = _load("users.json")

    # Helpers for validation
    def _match(pat, val):
        return isinstance(val, str) and re.match(pat, val) is not None

    sb_id_pat = r"^sb_srv_[0-9A-Z]{4,}$"
    usr_id_pat = r"^usr_[0-9A-Z]{4,}$"
    proj_pat = r"^[a-z0-9]{20}$"

    try:
        if action == "list":
            if owner_user_id is not None and not _match(usr_id_pat, owner_user_id):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "owner_user_id must match ^usr_[0-9A-Z]{4,}$")
            if supabase_project_ref is not None and not _match(proj_pat, supabase_project_ref):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "supabase_project_ref must match ^[a-z0-9]{20}$")
            if status is not None and status not in ("linked", "disabled", "revoked"):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "status must be one of: linked, disabled, revoked")
            if limit is None:
                limit = 50
            if not isinstance(limit, int) or limit < 1 or limit > 200:
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

            start_index = 0
            if cursor is not None:
                if not isinstance(cursor, str):
                    latency = (time.time() - start) * 1000
                    _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "cursor must be a string")
                # cursor format: idx:<int>
                if not cursor.startswith("idx:"):
                    latency = (time.time() - start) * 1000
                    _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Invalid cursor")
                try:
                    start_index = int(cursor.split(":", 1)[1])
                    if start_index < 0:
                        raise ValueError()
                except ValueError:
                    latency = (time.time() - start) * 1000
                    _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "Invalid cursor")

            # Visibility: servers owned by this user
            rows = [s for s in servers if s.get("owner_user_id") == uid]

            # Optional filters
            if owner_user_id is not None:
                # For safety, only allow filtering to self (still "visible to authenticated user")
                if owner_user_id != uid:
                    rows = []
                else:
                    rows = [s for s in rows if s.get("owner_user_id") == owner_user_id]
            if supabase_project_ref is not None:
                rows = [s for s in rows if s.get("supabase_project_ref") == supabase_project_ref]
            if status is not None:
                rows = [s for s in rows if s.get("status") == status]

            # Stable sort by created_at then id
            def _key(s):
                dt = _parse_dt(s.get("created_at")) or datetime.datetime.min
                return (dt, s.get("id") or "")
            rows.sort(key=_key)

            total = len(rows)
            page = rows[start_index:start_index + limit]
            next_cursor = None
            has_more = start_index + limit < total
            if has_more:
                next_cursor = f"idx:{start_index + limit}"

            latency = (time.time() - start) * 1000
            _log_call(endpoint, identifier, "ok", latency, user_id=uid, meta={"action": "list"})
            return {"data": page, "meta": {"total": total, "limit": limit, "cursor": cursor, "has_more": has_more, "next_cursor": next_cursor}}

        if action == "get":
            if id is None or not _match(sb_id_pat, id):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "id is required and must match ^sb_srv_[0-9A-Z]{4,}$")

            row = next((s for s in servers if s.get("id") == id and s.get("owner_user_id") == uid), None)
            if not row:
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="NOT_FOUND")
                return _err("NOT_FOUND", "Supabase server not found")

            latency = (time.time() - start) * 1000
            _log_call(endpoint, identifier, "ok", latency, user_id=uid, meta={"action": "get"})
            return {"data": row}

        if action == "create":
            if body is None or not isinstance(body, dict):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "body must be an object for action=create")

            ouid = body.get("owner_user_id")
            pref = body.get("supabase_project_ref")
            name = body.get("name")
            api_base_url = body.get("api_base_url")
            region = body.get("region")
            st = body.get("status", "linked")

            if ouid is None or not _match(usr_id_pat, ouid):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "body.owner_user_id is required and must match ^usr_[0-9A-Z]{4,}$")
            if pref is None or not _match(proj_pat, pref):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "body.supabase_project_ref is required and must match ^[a-z0-9]{20}$")
            if not isinstance(name, str) or not (1 <= len(name) <= 120):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "body.name is required and must be 1..120 characters")
            if not _valid_uri_https(api_base_url):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "body.api_base_url must be a valid https:// URI")
            if region is not None and not isinstance(region, str):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "body.region must be a string if provided")
            if st not in ("linked", "disabled", "revoked"):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "body.status must be one of: linked, disabled, revoked")

            # Owner must be the authenticated user (visibility & policy)
            if ouid != uid:
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="UNAUTHORIZED")
                return _err("UNAUTHORIZED", "Cannot create server for a different owner_user_id")

            owner = next((u for u in users if u.get("id") == ouid), None)
            if not owner:
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="NOT_FOUND")
                return _err("NOT_FOUND", "owner_user_id does not reference an existing user")
            if owner.get("status") != "active":
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="UNAUTHORIZED")
                return _err("UNAUTHORIZED", "Owning user is not active")

            # Unique(owner_user_id, supabase_project_ref)
            if any(s.get("owner_user_id") == ouid and s.get("supabase_project_ref") == pref for s in servers):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="CONFLICT")
                return _err("CONFLICT", "Supabase server already linked for this owner_user_id and supabase_project_ref")

            new_id = _gen_id("sb_srv")
            now = _now()
            row = {
                "id": new_id,
                "owner_user_id": ouid,
                "supabase_project_ref": pref,
                "name": name,
                "api_base_url": api_base_url,
                "region": region,
                "status": st,
                "created_at": now,
                "updated_at": now,
            }
            servers.append(row)
            _save("supabase_servers.json", servers)

            latency = (time.time() - start) * 1000
            _log_call(endpoint, identifier, "ok", latency, user_id=uid, meta={"action": "create"})
            return {"data": row}

        if action == "update":
            if id is None or not _match(sb_id_pat, id):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "id is required and must match ^sb_srv_[0-9A-Z]{4,}$")
            if body is None or not isinstance(body, dict):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "body must be an object for action=update")

            idx = None
            for i, s in enumerate(servers):
                if s.get("id") == id and s.get("owner_user_id") == uid:
                    idx = i
                    break
            if idx is None:
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="NOT_FOUND")
                return _err("NOT_FOUND", "Supabase server not found")

            row = servers[idx]

            if row.get("status") == "revoked":
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Revoked servers cannot be updated")

            # Validate and apply fields
            if "owner_user_id" in body and body.get("owner_user_id") != row.get("owner_user_id"):
                latency = (time.time() - start) * 1000
                _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "owner_user_id cannot be changed")

            if "supabase_project_ref" in body:
                new_pref = body.get("supabase_project_ref")
                if not _match(proj_pat, new_pref):
                    latency = (time.time() - start) * 1000
                    _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "supabase_project_ref must match ^[a-z0-9]{20}$")
                if new_pref != row.get("supabase_project_ref"):
                    # enforce unique(owner_user_id, supabase_project_ref)
                    if any(s.get("id") != row.get("id") and s.get("owner_user_id") == uid and s.get("supabase_project_ref") == new_pref for s in servers):
                        latency = (time.time() - start) * 1000
                        _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="CONFLICT")
                        return _err("CONFLICT", "Another server already uses this supabase_project_ref for this owner")
                    row["supabase_project_ref"] = new_pref

            if "name" in body:
                new_name = body.get("name")
                if not isinstance(new_name, str) or not (1 <= len(new_name) <= 120):
                    latency = (time.time() - start) * 1000
                    _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "name must be 1..120 characters")
                row["name"] = new_name

            if "api_base_url" in body:
                new_url = body.get("api_base_url")
                if not _valid_uri_https(new_url):
                    latency = (time.time() - start) * 1000
                    _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "api_base_url must be a valid https:// URI")
                row["api_base_url"] = new_url

            if "region" in body:
                new_region = body.get("region")
                if new_region is not None and not isinstance(new_region, str):
                    latency = (time.time() - start) * 1000
                    _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "region must be a string if provided")
                row["region"] = new_region

            if "status" in body:
                new_status = body.get("status")
                if new_status not in ("linked", "disabled", "revoked"):
                    latency = (time.time() - start) * 1000
                    _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", "status must be one of: linked, disabled, revoked")
                old_status = row.get("status")
                transitions = {
                    "linked": ["disabled", "revoked"],
                    "disabled": ["linked", "revoked"],
                    "revoked": [],
                }
                if new_status != old_status:
                    if new_status not in transitions.get(old_status, []):
                        latency = (time.time() - start) * 1000
                        _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="INVALID_TRANSITION")
                        return _err("INVALID_TRANSITION", f"Cannot transition status from {old_status} to {new_status}")
                    row["status"] = new_status

            row["updated_at"] = _now()
            servers[idx] = row
            _save("supabase_servers.json", servers)

            latency = (time.time() - start) * 1000
            _log_call(endpoint, identifier, "ok", latency, user_id=uid, meta={"action": "update"})
            return {"data": row}

        latency = (time.time() - start) * 1000
        _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Unsupported action")
    except (TypeError, ValueError) as e:
        latency = (time.time() - start) * 1000
        _log_call(endpoint, identifier, "error", latency, user_id=uid, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid input", detail=str(e))

def Credentials(action, credential, id=None, user_id=None, type=None, status=None, limit=None, cursor=None, body=None, **_extra):
    import json, os, datetime, base64, hashlib, hmac, secrets, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0263000" if __import__("os").path.isdir("./environment_mix/0263000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    # ---------- request log helpers (best-effort; schema may not include) ----------
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError("not a string datetime")
        # Accept ...Z or offset
        if s.endswith("Z"):
            s2 = s[:-1] + "+00:00"
        else:
            s2 = s
        return datetime.datetime.fromisoformat(s2)

    def _get_reqlog_filename():
        # try a few conventional names
        for fn in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _log(status_code, credential_id=None, meta=None):
        fn = _get_reqlog_filename()
        if not fn:
            return
        rows = _load(fn)
        row = {
            "id": f"req_{secrets.token_hex(8)}",
            "endpoint": "Credentials",
            "action": action,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _iso(now),
        }
        if isinstance(meta, dict):
            row.update(meta)
        rows.append(row)
        _save(fn, rows)

    # ---------- validation ----------
    try:
        if not isinstance(action, str):
            _log(400, None)
            return _err("VALIDATION_ERROR", "action must be a string")
        if action not in ("list", "get", "create", "update"):
            _log(400, None)
            return _err("VALIDATION_ERROR", "Invalid action")
        if not isinstance(credential, str) or not credential:
            _log(401, None)
            return _err("VALIDATION_ERROR", "credential must be a non-empty string")

        if id is not None:
            if not isinstance(id, str) or not re.match(r"^cred_[0-9A-Z]{4,}$", id):
                _log(400, None)
                return _err("VALIDATION_ERROR", "id is invalid")

        if user_id is not None:
            if not isinstance(user_id, str) or not re.match(r"^usr_[0-9A-Z]{4,}$", user_id):
                _log(400, None)
                return _err("VALIDATION_ERROR", "user_id is invalid")

        if type is not None:
            if type not in ("pat", "oauth"):
                _log(400, None)
                return _err("VALIDATION_ERROR", "type is invalid")

        if status is not None:
            if status not in ("active", "rotated", "revoked"):
                _log(400, None)
                return _err("VALIDATION_ERROR", "status is invalid")

        if limit is not None:
            if not isinstance(limit, int) or limit < 1 or limit > 200:
                _log(400, None)
                return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

        if cursor is not None and not isinstance(cursor, str):
            _log(400, None)
            return _err("VALIDATION_ERROR", "cursor must be a string")

        if body is not None and not isinstance(body, dict):
            _log(400, None)
            return _err("VALIDATION_ERROR", "body must be an object")
    except Exception as e:
        _log(500, None)
        return _err("VALIDATION_ERROR", "Invalid request", detail=str(e))

    # ---------- load datastore ----------
    users = _load("users.json")
    creds = _load("credentials.json")
    sessions = _load("auth_sessions.json")

    # ---------- authenticate ambiently via explicit credential parameter ----------
    # Accept either a credential.id (cred_...) or client-visible value = secret_fingerprint.
    # Never compare to secret_ciphertext.
    acting_cred = None
    if isinstance(credential, str) and credential:
        if re.match(r"^cred_[0-9A-Z]{4,}$", credential):
            for c in creds:
                if c.get("id") == credential:
                    acting_cred = c
                    break
        if acting_cred is None:
            for c in creds:
                if c.get("secret_fingerprint") == credential:
                    acting_cred = c
                    break

    if acting_cred is None:
        _log(401, None)
        return _err("UNAUTHORIZED", "Invalid credential")

    acting_user_id = acting_cred.get("user_id")
    acting_user = next((u for u in users if u.get("id") == acting_user_id), None)
    if not acting_user or acting_user.get("status") != "active":
        _log(401, acting_cred.get("id"))
        return _err("UNAUTHORIZED", "User not authorized")

    # ---------- helpers ----------
    def _public_cred(c):
        # Never return secret material fields. Return metadata only.
        out = {}
        for k in ("id", "user_id", "type", "label", "secret_fingerprint", "expires_at", "last_used_at", "status", "created_at", "updated_at"):
            if k in c:
                out[k] = c.get(k)
        return out

    def _compat_types(filter_type):
        # API layer's "pat"/"oauth" maps to stored types.
        if filter_type is None:
            return None
        if filter_type == "pat":
            return {"supabase_pat"}
        return {"oauth_access_token", "oauth_refresh_token"}

    def _new_id(prefix):
        # Simple ULID-like (not real ULID but fits pattern): prefix + base32-ish uppercase
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        s = "".join(secrets.choice(alphabet) for _ in range(10))
        return f"{prefix}_{s}"

    def _hmac_fingerprint(secret_plaintext):
        # Derive fingerprint using server-held key. Store key in mcp_settings global row if present, else local constant.
        settings = _load("mcp_settings.json")
        key = None
        for r in settings:
            if r.get("scope") == "global" and r.get("status") == "active":
                key = r.get("hmac_key")
                break
        if not isinstance(key, str) or not key:
            key = "local-dev-hmac-key"
        dig = hmac.new(key.encode("utf-8"), secret_plaintext.encode("utf-8"), hashlib.sha256).hexdigest()
        return f"hmacsha256_{dig}"

    def _encrypt_secret(secret_plaintext):
        # Offline approved envelope-like scheme placeholder: store version + random salt + XOR stream using HMAC-derived keystream.
        # Not plaintext; reversible only with server key. This is an approximation for offline datastore.
        settings = _load("mcp_settings.json")
        key = None
        for r in settings:
            if r.get("scope") == "global" and r.get("status") == "active":
                key = r.get("enc_key")
                break
        if not isinstance(key, str) or not key:
            key = "local-dev-enc-key"
        salt = secrets.token_bytes(16)
        pt = secret_plaintext.encode("utf-8")
        stream = hmac.new(key.encode("utf-8"), salt, hashlib.sha256).digest()
        # extend stream
        out = bytearray()
        i = 0
        while len(out) < len(pt):
            blk = hmac.new(stream, salt + i.to_bytes(4, "big"), hashlib.sha256).digest()
            out.extend(blk)
            i += 1
        ct = bytes([a ^ b for a, b in zip(pt, out[: len(pt)])])
        payload = b"v1:" + salt + b":" + ct
        return "encv1_" + base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _transition_allowed(old, new):
        allowed = {
            "active": {"rotated", "revoked"},
            "rotated": {"revoked"},
            "revoked": set(),
        }
        return new in allowed.get(old, set())

    # ---------- actions ----------
    if action == "list":
        # default limit
        lim = limit if limit is not None else 50
        # cursor is base64 of last id
        start_after = None
        if cursor:
            try:
                raw = base64.urlsafe_b64decode(cursor.encode("ascii") + b"===").decode("utf-8")
                if raw.startswith("after:"):
                    start_after = raw.split("after:", 1)[1]
            except Exception:
                _log(400, acting_cred.get("id"))
                return _err("VALIDATION_ERROR", "Invalid cursor")

        filtered = creds

        # acting user can only see own credentials (realistic policy)
        # If user_id filter provided and not equal to acting user -> unauthorized
        if user_id is not None and user_id != acting_user_id:
            _log(401, acting_cred.get("id"))
            return _err("UNAUTHORIZED", "Cannot list credentials for another user")
        filtered = [c for c in filtered if c.get("user_id") == acting_user_id]

        if type is not None:
            compat = _compat_types(type)
            filtered = [c for c in filtered if c.get("type") in compat]
        if status is not None:
            filtered = [c for c in filtered if c.get("status") == status]

        # sort by created_at desc then id desc
        def _key(c):
            return (c.get("created_at") or "", c.get("id") or "")
        filtered.sort(key=_key, reverse=True)

        if start_after:
            # find first item strictly after cursor in this sorted order
            idx = 0
            for i, c in enumerate(filtered):
                if c.get("id") == start_after:
                    idx = i + 1
                    break
            filtered = filtered[idx:]

        page = filtered[:lim]
        next_cursor = None
        has_more = len(filtered) > lim
        if has_more and page:
            token = "after:" + page[-1].get("id", "")
            next_cursor = base64.urlsafe_b64encode(token.encode("utf-8")).decode("ascii").rstrip("=")

        # update last_used_at for acting credential upon successful call
        for c in creds:
            if c.get("id") == acting_cred.get("id"):
                c["last_used_at"] = _iso(now)
                c["updated_at"] = c.get("updated_at") or _iso(now)
                break
        _save("credentials.json", creds)

        _log(200, acting_cred.get("id"))
        return {
            "data": [_public_cred(c) for c in page],
            "meta": {"total": len(filtered) if start_after is None else None, "limit": lim, "has_more": has_more, "next_cursor": next_cursor},
        }

    if action == "get":
        if not id:
            _log(400, acting_cred.get("id"))
            return _err("VALIDATION_ERROR", "id is required for action=get")
        c = next((x for x in creds if x.get("id") == id), None)
        if c is None:
            _log(404, acting_cred.get("id"))
            return _err("NOT_FOUND", "Credential not found")
        if c.get("user_id") != acting_user_id:
            _log(401, acting_cred.get("id"))
            return _err("UNAUTHORIZED", "Cannot access this credential")

        # mark last_used_at for acting credential
        for cc in creds:
            if cc.get("id") == acting_cred.get("id"):
                cc["last_used_at"] = _iso(now)
                cc["updated_at"] = _iso(now)
                break
        _save("credentials.json", creds)

        _log(200, acting_cred.get("id"))
        return {"data": _public_cred(c)}

    if action == "create":
        b = body or {}
        # validate create fields
        uid = b.get("user_id")
        t = b.get("type")
        label = b.get("label")
        secret_plaintext = b.get("secret_plaintext")
        exp = b.get("expires_at")

        if not isinstance(uid, str) or not re.match(r"^usr_[0-9A-Z]{4,}$", uid):
            _log(400, acting_cred.get("id"))
            return _err("VALIDATION_ERROR", "body.user_id is required and must be a valid usr_ id")
        if uid != acting_user_id:
            _log(401, acting_cred.get("id"))
            return _err("UNAUTHORIZED", "Cannot create credential for another user")
        if t not in ("pat", "oauth"):
            _log(400, acting_cred.get("id"))
            return _err("VALIDATION_ERROR", "body.type is required and must be one of: pat, oauth")
        if not isinstance(secret_plaintext, str) or len(secret_plaintext) < 1:
            _log(400, acting_cred.get("id"))
            return _err("VALIDATION_ERROR", "body.secret_plaintext is required")

        if label is not None:
            if not isinstance(label, str) or not (1 <= len(label) <= 80):
                _log(400, acting_cred.get("id"))
                return _err("VALIDATION_ERROR", "body.label must be a string of length 1..80")

        expires_at = None
        if exp is not None:
            try:
                expires_at = _parse_dt(exp)
            except Exception:
                _log(400, acting_cred.get("id"))
                return _err("VALIDATION_ERROR", "body.expires_at must be RFC3339 date-time")
            if expires_at.tzinfo is None:
                expires_at = expires_at.replace(tzinfo=datetime.timezone.utc)
            # constraint: expires_at is null or > created_at
            if expires_at <= now:
                _log(400, acting_cred.get("id"))
                return _err("VALIDATION_ERROR", "body.expires_at must be in the future")

        # user must exist and be active
        u = next((x for x in users if x.get("id") == uid), None)
        if not u:
            _log(404, acting_cred.get("id"))
            return _err("NOT_FOUND", "User not found")
        if u.get("status") != "active":
            _log(409, acting_cred.get("id"))
            return _err("CONFLICT", "User is not active")

        stored_type = "supabase_pat" if t == "pat" else "oauth_access_token"

        fp = _hmac_fingerprint(secret_plaintext)
        # unique(user_id, secret_fingerprint)
        for c in creds:
            if c.get("user_id") == uid and c.get("secret_fingerprint") == fp:
                # idempotent-ish: return existing metadata (do not store plaintext again)
                _log(200, acting_cred.get("id"))
                return {"data": _public_cred(c), "meta": {"idempotent": True}}

        ciphertext = _encrypt_secret(secret_plaintext)
        new_id = _new_id("cred")
        created = _iso(now)
        row = {
            "id": new_id,
            "user_id": uid,
            "type": stored_type,
            "label": label,
            "secret_ciphertext": ciphertext,
            "secret_fingerprint": fp,
            "expires_at": _iso(expires_at) if expires_at else None,
            "last_used_at": None,
            "status": "active",
            "created_at": created,
            "updated_at": created,
        }
        creds.append(row)

        # update last_used_at for acting credential (the one used to call)
        for cc in creds:
            if cc.get("id") == acting_cred.get("id"):
                cc["last_used_at"] = _iso(now)
                cc["updated_at"] = _iso(now)
                break

        _save("credentials.json", creds)
        _log(201, acting_cred.get("id"))
        return {"data": _public_cred(row)}

    if action == "update":
        if not id:
            _log(400, acting_cred.get("id"))
            return _err("VALIDATION_ERROR", "id is required for action=update")
        b = body or {}
        c = next((x for x in creds if x.get("id") == id), None)
        if c is None:
            _log(404, acting_cred.get("id"))
            return _err("NOT_FOUND", "Credential not found")
        if c.get("user_id") != acting_user_id:
            _log(401, acting_cred.get("id"))
            return _err("UNAUTHORIZED", "Cannot update this credential")

        # Disallow secret_plaintext on update
        if "secret_plaintext" in b:
            _log(400, acting_cred.get("id"))
            return _err("VALIDATION_ERROR", "secret_plaintext is only accepted on create")

        changed = False

        if "label" in b:
            lbl = b.get("label")
            if lbl is not None:
                if not isinstance(lbl, str) or not (1 <= len(lbl) <= 80):
                    _log(400, acting_cred.get("id"))
                    return _err("VALIDATION_ERROR", "body.label must be a string of length 1..80")
            c["label"] = lbl
            changed = True

        if "expires_at" in b:
            exp = b.get("expires_at")
            if exp is None:
                c["expires_at"] = None
                changed = True
            else:
                try:
                    dt = _parse_dt(exp)
                except Exception:
                    _log(400, acting_cred.get("id"))
                    return _err("VALIDATION_ERROR", "body.expires_at must be RFC3339 date-time")
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                if dt <= now:
                    _log(400, acting_cred.get("id"))
                    return _err("VALIDATION_ERROR", "body.expires_at must be in the future")
                c["expires_at"] = _iso(dt)
                changed = True

        if "status" in b:
            new_status = b.get("status")
            if new_status not in ("active", "rotated", "revoked"):
                _log(400, acting_cred.get("id"))
                return _err("VALIDATION_ERROR", "body.status is invalid")
            old_status = c.get("status")
            if new_status != old_status:
                if not _transition_allowed(old_status, new_status):
                    _log(409, acting_cred.get("id"))
                    return _err("INVALID_TRANSITION", f"Cannot transition credential from {old_status} to {new_status}")
                c["status"] = new_status
                changed = True

                # business rule: revoking a credential revokes all active auth_sessions referencing it in same transaction
                if new_status == "revoked":
                    for s in sessions:
                        if s.get("credential_id") == c.get("id") and s.get("status") == "active":
                            s["status"] = "revoked"
                            s["revoked_at"] = _iso(now)
                            s["updated_at"] = _iso(now)

        if not changed:
            _log(404, acting_cred.get("id"))
            return _err("NOT_FOUND", "No updates applied")

        c["updated_at"] = _iso(now)

        # mark last_used_at for acting credential (call credential)
        for cc in creds:
            if cc.get("id") == acting_cred.get("id"):
                cc["last_used_at"] = _iso(now)
                cc["updated_at"] = _iso(now)
                break

        _save("auth_sessions.json", sessions)
        _save("credentials.json", creds)
        _log(200, acting_cred.get("id"))
        return {"data": _public_cred(c)}

    _log(400, acting_cred.get("id"))
    return _err("VALIDATION_ERROR", "Unsupported action")

def Auth_Sessions(action, credential, id=None, user_id=None, status=None, limit=None, cursor=None, body=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0263000" if __import__("os").path.isdir("./environment_mix/0263000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _is_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def _match_pat(pref, s):
        return isinstance(s, str) and re.match(r"^" + re.escape(pref) + r"_[0-9A-Z]{4,}$", s) is not None

    def _load_rows(name):
        d = _load(name)
        if isinstance(d, list):
            return d
        # tolerate {"rows":[...]} shape if present
        if isinstance(d, dict) and isinstance(d.get("rows"), list):
            return d["rows"]
        return []

    def _save_rows(name, rows, original):
        if isinstance(original, list) or original == []:
            _save(name, rows)
        elif isinstance(original, dict) and isinstance(original.get("rows"), list):
            original["rows"] = rows
            _save(name, original)
        else:
            _save(name, rows)

    # ---- request logging / quota/rate limiting if logs collection exists ----
    def _find_log_collection():
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _append_log(log_fname, row):
        if not log_fname:
            return
        orig = _load(log_fname)
        logs = orig if isinstance(orig, list) else (orig.get("rows") if isinstance(orig, dict) and isinstance(orig.get("rows"), list) else [])
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        if isinstance(orig, dict) and isinstance(orig.get("rows"), list):
            orig["rows"] = logs
            _save(log_fname, orig)
        else:
            _save(log_fname, logs)

    def _enforce_limits(log_fname, resolved_cred_id):
        # If no log collection, do nothing (cannot enforce).
        if not log_fname:
            return None
        orig = _load(log_fname)
        logs = orig if isinstance(orig, list) else (orig.get("rows") if isinstance(orig, dict) and isinstance(orig.get("rows"), list) else [])
        if not isinstance(logs, list):
            logs = []
        # rate limit: 60/min per credential (or per caller if no cred id)
        key = resolved_cred_id or "anonymous"
        cutoff = now - datetime.timedelta(minutes=1)
        n_min = 0
        for r in logs:
            if r.get("credential_id") != key:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff:
                n_min += 1
        if n_min >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        # daily quota: 10k/day per credential
        cutoff_d = now - datetime.timedelta(days=1)
        n_day = 0
        for r in logs:
            if r.get("credential_id") != key:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= cutoff_d:
                n_day += 1
        if n_day >= 10000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    log_fname = _find_log_collection()

    # ---- validate request envelope ----
    if action not in ("list", "get", "create", "update"):
        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": None,
            "user_id": None,
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return _err("VALIDATION_ERROR", "Invalid action.", field="action")

    if not _is_str(credential):
        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": None,
            "user_id": None,
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return _err("VALIDATION_ERROR", "credential must be a non-empty string.", field="credential")

    if id is not None and not _match_pat("sess", id):
        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": None,
            "user_id": None,
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return _err("VALIDATION_ERROR", "Invalid id format.", field="id")

    if user_id is not None and not _match_pat("usr", user_id):
        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": None,
            "user_id": None,
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return _err("VALIDATION_ERROR", "Invalid user_id format.", field="user_id")

    if status is not None and status not in ("active", "expired", "revoked"):
        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": None,
            "user_id": None,
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")

    if limit is not None:
        if not _is_int(limit) or not (1 <= limit <= 200):
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": None,
                "user_id": None,
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if body is not None and not isinstance(body, dict):
        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": None,
            "user_id": None,
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return _err("VALIDATION_ERROR", "body must be an object.", field="body")

    # ---- load datastore ----
    creds_orig = _load("credentials.json")
    sessions_orig = _load("auth_sessions.json")
    users_orig = _load("users.json")
    settings_orig = _load("mcp_settings.json")

    credentials = _load_rows("credentials.json")
    sessions = _load_rows("auth_sessions.json")
    users = _load_rows("users.json")
    settings = _load_rows("mcp_settings.json")

    # ---- authenticate (match credential param to credential.id OR secret_fingerprint OR session.id) ----
    # credential param is described as "Bearer access token or API key"; in this store, we can match:
    #  - credentials.id
    #  - credentials.secret_fingerprint (client-visible surrogate)
    #  - active auth session id (sess_...) which maps to session.credential_id (may be null when auth_mode=none)
    resolved_cred = next((c for c in credentials if c.get("id") == credential or c.get("secret_fingerprint") == credential), None)
    resolved_sess = None
    if resolved_cred is None and _match_pat("sess", credential):
        resolved_sess = next((s for s in sessions if s.get("id") == credential), None)

    acting_user = None
    acting_cred_id = None

    def _session_is_active_valid(sess_row):
        if not sess_row or sess_row.get("status") != "active":
            return False
        if sess_row.get("revoked_at") is not None:
            return False
        exp = _parse_dt(sess_row.get("expires_at"))
        if exp is not None and exp <= now:
            return False
        return True

    # If session id provided, allow as credential only if session is currently active/valid.
    if resolved_sess is not None:
        # auto-expire if needed (business rule)
        exp = _parse_dt(resolved_sess.get("expires_at"))
        if resolved_sess.get("status") == "active" and exp is not None and exp <= now:
            # transition to expired
            resolved_sess["status"] = "expired"
            resolved_sess["updated_at"] = now_iso
            # persist the transition
            _save_rows("auth_sessions.json", sessions, sessions_orig)
        if not _session_is_active_valid(resolved_sess):
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": None,
                "user_id": resolved_sess.get("user_id"),
                "status": "error",
                "error_code": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("UNAUTHORIZED", "Invalid or inactive session credential.")
        acting_user = next((u for u in users if u.get("id") == resolved_sess.get("user_id")), None)
        acting_cred_id = resolved_sess.get("credential_id")  # may be null
    elif resolved_cred is not None:
        # enforce credential active & not expired
        if resolved_cred.get("status") != "active":
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": resolved_cred.get("id"),
                "user_id": resolved_cred.get("user_id"),
                "status": "error",
                "error_code": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("UNAUTHORIZED", "Credential is not active.")
        expc = _parse_dt(resolved_cred.get("expires_at"))
        if expc is not None and expc <= now:
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": resolved_cred.get("id"),
                "user_id": resolved_cred.get("user_id"),
                "status": "error",
                "error_code": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("UNAUTHORIZED", "Credential expired.")
        acting_user = next((u for u in users if u.get("id") == resolved_cred.get("user_id")), None)
        acting_cred_id = resolved_cred.get("id")
    else:
        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": None,
            "user_id": None,
            "status": "error",
            "error_code": "UNAUTHORIZED",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return _err("UNAUTHORIZED", "Invalid credential.")

    if not acting_user or acting_user.get("status") != "active":
        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": acting_cred_id,
            "user_id": (acting_user or {}).get("id"),
            "status": "error",
            "error_code": "UNAUTHORIZED",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return _err("UNAUTHORIZED", "User is not active.")

    # enforce rate/quota using resolved credential id (or anonymous if none)
    limit_err = _enforce_limits(log_fname, acting_cred_id or "anonymous")
    if limit_err:
        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": acting_cred_id or "anonymous",
            "user_id": acting_user.get("id"),
            "status": "error",
            "error_code": limit_err["error"]["code"],
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return limit_err

    # ---- helper: auto-expire sessions where expires_at <= now (business rule) ----
    changed = False
    for s in sessions:
        if s.get("status") == "active":
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now:
                s["status"] = "expired"
                s["updated_at"] = now_iso
                changed = True
    if changed:
        _save_rows("auth_sessions.json", sessions, sessions_orig)

    # settings: determine auth_mode for acting user (prefer active user scope over global)
    def _active_setting(scope, uid=None):
        for r in settings:
            if r.get("status") != "active":
                continue
            if r.get("scope") != scope:
                continue
            if scope == "global" and r.get("user_id") is None:
                return r
            if scope == "user" and r.get("user_id") == uid:
                return r
        return None

    user_setting = _active_setting("user", acting_user.get("id"))
    global_setting = _active_setting("global", None)
    effective_setting = user_setting or global_setting
    auth_mode = (effective_setting or {}).get("auth_mode") or "none"

    # ---- operations ----
    if action == "list":
        # only allow listing own sessions unless explicit user_id matches caller
        target_uid = user_id or acting_user.get("id")
        if target_uid != acting_user.get("id"):
            # no admin model in schema; refuse
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("UNAUTHORIZED", "Cannot list sessions for other users.")

        filtered = [s for s in sessions if s.get("user_id") == target_uid]
        if status is not None:
            filtered = [s for s in filtered if s.get("status") == status]

        # sort newest first
        def _k(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return dt
        filtered.sort(key=_k, reverse=True)

        total = len(filtered)

        start = 0
        if cursor is not None:
            if not isinstance(cursor, str):
                _append_log(log_fname, {
                    "id": "req_" + secrets.token_hex(8),
                    "endpoint": "Auth Sessions",
                    "tool": "Auth Sessions",
                    "credential_id": acting_cred_id or "anonymous",
                    "user_id": acting_user.get("id"),
                    "status": "error",
                    "error_code": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso
                })
                return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
            try:
                start = int(cursor)
                if start < 0:
                    raise ValueError()
            except Exception:
                _append_log(log_fname, {
                    "id": "req_" + secrets.token_hex(8),
                    "endpoint": "Auth Sessions",
                    "tool": "Auth Sessions",
                    "credential_id": acting_cred_id or "anonymous",
                    "user_id": acting_user.get("id"),
                    "status": "error",
                    "error_code": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso
                })
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

        lim = limit or 50
        page = filtered[start:start + lim]
        has_more = (start + lim) < total
        next_cursor = str(start + lim) if has_more else None

        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": acting_cred_id or "anonymous",
            "user_id": acting_user.get("id"),
            "status": "ok",
            "error_code": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

    if action == "get":
        if id is None:
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("VALIDATION_ERROR", "id is required for action=get.", field="id")
        sess = next((s for s in sessions if s.get("id") == id), None)
        if sess is None or sess.get("user_id") != acting_user.get("id"):
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "NOT_FOUND",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("NOT_FOUND", "Session not found.")
        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": acting_cred_id or "anonymous",
            "user_id": acting_user.get("id"),
            "status": "ok",
            "error_code": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return {"data": sess}

    if action == "create":
        b = body or {}
        if not isinstance(b, dict):
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("VALIDATION_ERROR", "body must be an object.", field="body")

        target_uid = b.get("user_id") or acting_user.get("id")
        if not _match_pat("usr", target_uid):
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("VALIDATION_ERROR", "Invalid body.user_id.", field="body.user_id")

        if target_uid != acting_user.get("id"):
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("UNAUTHORIZED", "Cannot create sessions for other users.")

        # validate optional expires_at
        exp = _parse_dt(b.get("expires_at")) if "expires_at" in b else None
        if "expires_at" in b and exp is None and b.get("expires_at") is not None:
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("VALIDATION_ERROR", "expires_at must be RFC3339 date-time.", field="body.expires_at")
        if exp is not None and exp <= now:
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("VALIDATION_ERROR", "expires_at cannot be in the past.", field="body.expires_at")

        # determine required credential binding based on auth_mode
        cred_id = b.get("credential_id")
        if auth_mode in ("pat", "oauth"):
            if cred_id is None:
                _append_log(log_fname, {
                    "id": "req_" + secrets.token_hex(8),
                    "endpoint": "Auth Sessions",
                    "tool": "Auth Sessions",
                    "credential_id": acting_cred_id or "anonymous",
                    "user_id": acting_user.get("id"),
                    "status": "error",
                    "error_code": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso
                })
                return _err("VALIDATION_ERROR", "credential_id is required when auth_mode is pat/oauth.", field="body.credential_id")
            if not _match_pat("cred", cred_id):
                _append_log(log_fname, {
                    "id": "req_" + secrets.token_hex(8),
                    "endpoint": "Auth Sessions",
                    "tool": "Auth Sessions",
                    "credential_id": acting_cred_id or "anonymous",
                    "user_id": acting_user.get("id"),
                    "status": "error",
                    "error_code": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso
                })
                return _err("VALIDATION_ERROR", "Invalid credential_id format.", field="body.credential_id")

            c = next((x for x in credentials if x.get("id") == cred_id and x.get("user_id") == acting_user.get("id")), None)
            if c is None:
                _append_log(log_fname, {
                    "id": "req_" + secrets.token_hex(8),
                    "endpoint": "Auth Sessions",
                    "tool": "Auth Sessions",
                    "credential_id": acting_cred_id or "anonymous",
                    "user_id": acting_user.get("id"),
                    "status": "error",
                    "error_code": "NOT_FOUND",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso
                })
                return _err("NOT_FOUND", "Credential not found.")
            if c.get("status") != "active":
                _append_log(log_fname, {
                    "id": "req_" + secrets.token_hex(8),
                    "endpoint": "Auth Sessions",
                    "tool": "Auth Sessions",
                    "credential_id": cred_id,
                    "user_id": acting_user.get("id"),
                    "status": "error",
                    "error_code": "UNAUTHORIZED",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso
                })
                return _err("UNAUTHORIZED", "Credential is not active.")
            expc = _parse_dt(c.get("expires_at"))
            if expc is not None and expc <= now:
                _append_log(log_fname, {
                    "id": "req_" + secrets.token_hex(8),
                    "endpoint": "Auth Sessions",
                    "tool": "Auth Sessions",
                    "credential_id": cred_id,
                    "user_id": acting_user.get("id"),
                    "status": "error",
                    "error_code": "UNAUTHORIZED",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso
                })
                return _err("UNAUTHORIZED", "Credential expired.")
            # compatibility
            if auth_mode == "pat" and c.get("type") != "supabase_pat":
                _append_log(log_fname, {
                    "id": "req_" + secrets.token_hex(8),
                    "endpoint": "Auth Sessions",
                    "tool": "Auth Sessions",
                    "credential_id": cred_id,
                    "user_id": acting_user.get("id"),
                    "status": "error",
                    "error_code": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso
                })
                return _err("VALIDATION_ERROR", "Credential type incompatible with auth_mode=pat.", field="body.credential_id")
            if auth_mode == "oauth" and c.get("type") != "oauth_access_token":
                _append_log(log_fname, {
                    "id": "req_" + secrets.token_hex(8),
                    "endpoint": "Auth Sessions",
                    "tool": "Auth Sessions",
                    "credential_id": cred_id,
                    "user_id": acting_user.get("id"),
                    "status": "error",
                    "error_code": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso
                })
                return _err("VALIDATION_ERROR", "Credential type incompatible with auth_mode=oauth (requires oauth_access_token).", field="body.credential_id")
        else:
            # auth_mode none: credential_id must be absent or null
            if "credential_id" in b and b.get("credential_id") is not None:
                _append_log(log_fname, {
                    "id": "req_" + secrets.token_hex(8),
                    "endpoint": "Auth Sessions",
                    "tool": "Auth Sessions",
                    "credential_id": acting_cred_id or "anonymous",
                    "user_id": acting_user.get("id"),
                    "status": "error",
                    "error_code": "VALIDATION_ERROR",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso
                })
                return _err("VALIDATION_ERROR", "credential_id must be null when auth_mode is none.", field="body.credential_id")
            cred_id = None

        # status on create: if provided must be 'active' only
        if "status" in b and b.get("status") is not None and b.get("status") != "active":
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("VALIDATION_ERROR", "Only status='active' may be set on create.", field="body.status")

        # create session id
        new_id = "sess_" + secrets.token_hex(10).upper()
        new_row = {
            "id": new_id,
            "user_id": acting_user.get("id"),
            "credential_id": cred_id,
            "issued_at": now_iso,
            "expires_at": _dt_iso(exp) if exp is not None else None,
            "revoked_at": None,
            "status": "active",
            "created_at": now_iso,
            "updated_at": now_iso
        }

        sessions.append(new_row)
        _save_rows("auth_sessions.json", sessions, sessions_orig)

        # update last_used_at for bound credential on successful create
        if cred_id is not None:
            for c in credentials:
                if c.get("id") == cred_id:
                    c["last_used_at"] = now_iso
                    c["updated_at"] = now_iso
                    break
            _save_rows("credentials.json", credentials, creds_orig)

        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": acting_cred_id or "anonymous",
            "user_id": acting_user.get("id"),
            "status": "ok",
            "error_code": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return {"data": new_row}

    if action == "update":
        if id is None:
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("VALIDATION_ERROR", "id is required for action=update.", field="id")
        b = body or {}
        if not isinstance(b, dict):
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("VALIDATION_ERROR", "body must be an object.", field="body")

        sess = next((s for s in sessions if s.get("id") == id), None)
        if sess is None or sess.get("user_id") != acting_user.get("id"):
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "NOT_FOUND",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("NOT_FOUND", "Session not found.")

        # auto-expire if needed before applying update
        if sess.get("status") == "active":
            exp = _parse_dt(sess.get("expires_at"))
            if exp is not None and exp <= now:
                sess["status"] = "expired"
                sess["updated_at"] = now_iso
                _save_rows("auth_sessions.json", sessions, sessions_orig)

        new_status = b.get("status")
        if new_status is None:
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("VALIDATION_ERROR", "body.status is required for update.", field="body.status")
        if new_status not in ("active", "expired", "revoked"):
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("VALIDATION_ERROR", "Invalid status.", field="body.status")

        cur = sess.get("status")
        if cur == "active":
            if new_status != "revoked":
                _append_log(log_fname, {
                    "id": "req_" + secrets.token_hex(8),
                    "endpoint": "Auth Sessions",
                    "tool": "Auth Sessions",
                    "credential_id": acting_cred_id or "anonymous",
                    "user_id": acting_user.get("id"),
                    "status": "error",
                    "error_code": "INVALID_TRANSITION",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso
                })
                return _err("INVALID_TRANSITION", "Only active→revoked is allowed.")
            # revoke
            sess["status"] = "revoked"
            sess["revoked_at"] = now_iso
            sess["updated_at"] = now_iso
            _save_rows("auth_sessions.json", sessions, sessions_orig)
        else:
            # terminal sessions cannot change
            if new_status == cur:
                # idempotent no-op is allowed? Contract says no success without effect; treat as conflict
                _append_log(log_fname, {
                    "id": "req_" + secrets.token_hex(8),
                    "endpoint": "Auth Sessions",
                    "tool": "Auth Sessions",
                    "credential_id": acting_cred_id or "anonymous",
                    "user_id": acting_user.get("id"),
                    "status": "error",
                    "error_code": "INVALID_TRANSITION",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now_iso
                })
                return _err("INVALID_TRANSITION", "Session is terminal; no further updates allowed.")
            _append_log(log_fname, {
                "id": "req_" + secrets.token_hex(8),
                "endpoint": "Auth Sessions",
                "tool": "Auth Sessions",
                "credential_id": acting_cred_id or "anonymous",
                "user_id": acting_user.get("id"),
                "status": "error",
                "error_code": "INVALID_TRANSITION",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now_iso
            })
            return _err("INVALID_TRANSITION", "Cannot transition expired/revoked sessions.")

        _append_log(log_fname, {
            "id": "req_" + secrets.token_hex(8),
            "endpoint": "Auth Sessions",
            "tool": "Auth Sessions",
            "credential_id": acting_cred_id or "anonymous",
            "user_id": acting_user.get("id"),
            "status": "ok",
            "error_code": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now_iso
        })
        return {"data": sess}

    # should be unreachable due to action validation
    _append_log(log_fname, {
        "id": "req_" + secrets.token_hex(8),
        "endpoint": "Auth Sessions",
        "tool": "Auth Sessions",
        "credential_id": acting_cred_id or "anonymous",
        "user_id": acting_user.get("id"),
        "status": "error",
        "error_code": "VALIDATION_ERROR",
        "latency_ms": int((time.time() - t0) * 1000),
        "created_at": now_iso
    })
    return _err("VALIDATION_ERROR", "Invalid action.")
